import copy


class EightPuzzle:
    BLANK_TILE = 0
    GOAL_STATE = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]
    BOARD_SIZE = 3

    def __init__(self, initial_state):
        self.initial_state = copy.deepcopy(initial_state)
        self.goal_state = copy.deepcopy(self.GOAL_STATE)

    def find_blank(self, state):
        """Find the position of the blank tile (0)."""
        for i in range(self.BOARD_SIZE):
            for j in range(self.BOARD_SIZE):
                if state[i][j] == self.BLANK_TILE:
                    return i, j
        raise ValueError("Blank tile not found in state")

    def _swap_tiles(self, state, pos1, pos2):
        """Create a new state with two tiles swapped."""
        new_state = [row[:] for row in state]
        i1, j1 = pos1
        i2, j2 = pos2
        new_state[i1][j1], new_state[i2][j2] = new_state[i2][j2], new_state[i1][j1]
        return new_state

    def move(self, state, direction):
        """Move the blank tile in the given direction."""
        i, j = self.find_blank(state)
        if direction == 'up':
            return self._swap_tiles(state, (i, j), (i - 1, j))
        elif direction == 'down':
            return self._swap_tiles(state, (i, j), (i + 1, j))
        elif direction == 'left':
            return self._swap_tiles(state, (i, j), (i, j - 1))
        elif direction == 'right':
            return self._swap_tiles(state, (i, j), (i, j + 1))
        raise ValueError(f"Invalid direction: {direction}")

    def _can_move_up(self, i):
        return i > 0

    def _can_move_down(self, i):
        return i < self.BOARD_SIZE - 1

    def _can_move_left(self, j):
        return j > 0

    def _can_move_right(self, j):
        return j < self.BOARD_SIZE - 1

    def get_possible_moves(self, state):
        """Get all valid moves from the current state."""
        moves = []
        i, j = self.find_blank(state)

        if self._can_move_up(i):
            moves.append('up')
        if self._can_move_down(i):
            moves.append('down')
        if self._can_move_left(j):
            moves.append('left')
        if self._can_move_right(j):
            moves.append('right')

        return moves

    def _is_goal(self, state):
        """Check if the current state matches the goal state."""
        return state == self.goal_state

    def _add_to_open_list(self, open_list, new_state, path, move, closed_list):
        """Add a new state to the open list if not already closed."""
        if new_state not in closed_list:
            open_list.append((new_state, path + [move]))

    def solve(self):
        """Solve the 8-puzzle using BFS."""
        open_list = [(self.initial_state, [])]
        closed_list = []

        while open_list:
            current_state, path = open_list.pop(0)
            closed_list.append(current_state)

            if self._is_goal(current_state):
                return path

            for move in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move)
                self._add_to_open_list(open_list, new_state, path, move, closed_list)

        return None
